import unittest
from candidate import circular_shift


class TestCircularShift(unittest.TestCase):
    def test_two_digit_shift_by_one(self):
        self.assertEqual(circular_shift(12, 1), "21")

    def test_two_digit_shift_by_two(self):
        self.assertEqual(circular_shift(12, 2), "12")

    def test_three_digit_shift_by_one(self):
        self.assertEqual(circular_shift(123, 1), "312")

    def test_three_digit_shift_by_two(self):
        self.assertEqual(circular_shift(123, 2), "231")

    def test_three_digit_shift_by_three(self):
        self.assertEqual(circular_shift(123, 3), "123")

    def test_four_digit_shift_by_two(self):
        self.assertEqual(circular_shift(1234, 2), "3412")

    def test_four_digit_shift_by_three(self):
        self.assertEqual(circular_shift(1234, 3), "4123")

    def test_single_digit_shift_by_one(self):
        self.assertEqual(circular_shift(5, 1), "5")

    def test_single_digit_shift_greater_than_length(self):
        self.assertEqual(circular_shift(5, 2), "5")

    def test_shift_zero_returns_same_string(self):
        self.assertEqual(circular_shift(1234, 0), "1234")

    def test_shift_equal_to_length_returns_same(self):
        self.assertEqual(circular_shift(9876, 4), "9876")

    def test_shift_greater_than_length_reverses(self):
        self.assertEqual(circular_shift(123, 4), "321")

    def test_shift_greater_than_length_reverses_larger(self):
        self.assertEqual(circular_shift(12345, 10), "54321")

    def test_zero_value(self):
        self.assertEqual(circular_shift(0, 1), "0")

    def test_zero_value_shift_greater_than_length(self):
        self.assertEqual(circular_shift(0, 2), "0")

    def test_negative_number(self):
        self.assertEqual(circular_shift(-123, 1), "-321"[-1:] + "-123"[-1:-1:-1] if False else circular_shift(-123, 1))

    def test_negative_number_shift_one(self):
        s = str(-123)
        expected = s[len(s) - 1:] + s[:len(s) - 1]
        self.assertEqual(circular_shift(-123, 1), expected)

    def test_negative_number_shift_greater_than_length(self):
        s = str(-123)
        self.assertEqual(circular_shift(-123, 5), s[::-1])

    def test_large_number(self):
        self.assertEqual(circular_shift(100000, 1), "000001")

    def test_large_number_shift_greater_than_length(self):
        self.assertEqual(circular_shift(100000, 7), "000001"[::-1])

    def test_returns_string_type(self):
        self.assertIsInstance(circular_shift(123, 1), str)

    def test_repeated_digits(self):
        self.assertEqual(circular_shift(1111, 2), "1111")

    def test_repeated_digits_shift_greater(self):
        self.assertEqual(circular_shift(1111, 3), "1111")

    def test_shift_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            circular_shift(123, None)

    def test_x_none_produces_string_none(self):
        s = str(None)
        result = circular_shift(None, 1)
        expected = s[len(s) - 1:] + s[:len(s) - 1]
        self.assertEqual(result, expected)

    def test_x_none_shift_greater_than_length(self):
        s = str(None)
        self.assertEqual(circular_shift(None, 5), s[::-1])

    def test_float_input(self):
        self.assertEqual(circular_shift(1.23, 1), str(1.23)[len(str(1.23)) - 1:] + str(1.23)[:len(str(1.23)) - 1])

    def test_shift_by_one_multiple_times(self):
        self.assertEqual(circular_shift(12345, 1), "51234")
        self.assertEqual(circular_shift(12345, 2), "45123")
        self.assertEqual(circular_shift(12345, 3), "34512")
        self.assertEqual(circular_shift(12345, 4), "23451")
        self.assertEqual(circular_shift(12345, 5), "12345")

    def test_shift_negative_value(self):
        s = str(123)
        result = circular_shift(123, -1)
        self.assertEqual(result, s[len(s) - (-1):] + s[:len(s) - (-1)])

    def test_two_digit_number_various_shifts(self):
        self.assertEqual(circular_shift(99, 1), "99")
        self.assertEqual(circular_shift(99, 2), "99")
        self.assertEqual(circular_shift(99, 3), "99")

    def test_number_with_zeros_inside(self):
        self.assertEqual(circular_shift(101, 1), "110")
        self.assertEqual(circular_shift(101, 2), "011")

    def test_number_with_trailing_zeros(self):
        self.assertEqual(circular_shift(100, 1), "010")
        self.assertEqual(circular_shift(100, 2), "001")

    def test_number_with_trailing_zeros_shift_greater(self):
        self.assertEqual(circular_shift(100, 3), "001")


if __name__ == '__main__':
    unittest.main()
